import React, { useState, useEffect } from 'react';
import { Fingerprint, Key, LogIn, Eye, RotateCcw, Info, Loader2 } from 'lucide-react';

// Ethers.js v6 compatible implementation
const ethers = {
  Wallet: class {
    constructor(privateKey) {
      // Generate wallet from private key or create random
      if (!privateKey) {
        // Create random 32 bytes
        const array = new Uint8Array(32);
        crypto.getRandomValues(array);
        this.privateKey = '0x' + Array.from(array).map(b => b.toString(16).padStart(2, '0')).join('');
      } else {
        this.privateKey = privateKey.startsWith('0x') ? privateKey : '0x' + privateKey;
      }

      // Generate address from private key (simplified - using hash)
      this.address = this.generateAddress();
    }

    generateAddress() {
      // Simulate address generation (in production, use proper ECDSA)
      const hash = this.simpleHash(this.privateKey);
      return '0x' + hash.substring(0, 40);
    }

    simpleHash(str) {
      let hash = 0;
      for (let i = 0; i < str.length; i++) {
        const char = str.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash = hash & hash;
      }
      return Math.abs(hash).toString(16).padStart(40, '0');
    }

    async signMessage(message) {
      // Ethereum signed message format
      const prefix = `\x19Ethereum Signed Message:\n${message.length}`;
      const fullMessage = prefix + message;

      // Simple signature simulation (in production, use proper ECDSA)
      const hash = await this.hashMessage(fullMessage);
      const r = hash.substring(0, 64);
      const s = hash.substring(64, 128);
      const v = '1b'; // 27 in hex

      return '0x' + r + s + v;
    }

    async hashMessage(message) {
      const encoder = new TextEncoder();
      const data = encoder.encode(message);
      const hashBuffer = await crypto.subtle.digest('SHA-256', data);
      const hashArray = Array.from(new Uint8Array(hashBuffer));
      return hashArray.map(b => b.toString(16).padStart(2, '0')).join('').padEnd(130, '0');
    }
  }
};

const DIDAuthApp = () => {
  const [did, setDid] = useState(null);
  const [wallets, setWallets] = useState(null);
  const [statusMessage, setStatusMessage] = useState('Prêt');
  const [isLoading, setIsLoading] = useState(false);
  const [showKeys, setShowKeys] = useState(false);

  // Backend URL - adjust for your setup
  const BASE_URL = 'http://localhost:3000';

  useEffect(() => {
    loadOrCreateWallets();
  }, []);

  // 1. Load or create 3 wallets + DID
  const loadOrCreateWallets = async () => {
    setIsLoading(true);
    setStatusMessage('Chargement des clés...');

    try {
      // Check localStorage for existing keys
      const key1 = localStorage.getItem('wallet_key1');
      const key2 = localStorage.getItem('wallet_key2');
      const key3 = localStorage.getItem('wallet_key3');
      const savedDid = localStorage.getItem('did');

      if (!key1 || !key2 || !key3) {
        // Create new wallets
        const newWallets = [
          new ethers.Wallet(),
          new ethers.Wallet(),
          new ethers.Wallet()
        ];

        // Save to localStorage
        localStorage.setItem('wallet_key1', newWallets[0].privateKey);
        localStorage.setItem('wallet_key2', newWallets[1].privateKey);
        localStorage.setItem('wallet_key3', newWallets[2].privateKey);

        const newDid = `did:example:${Date.now()}`;
        localStorage.setItem('did', newDid);

        setWallets(newWallets);
        setDid(newDid);
        setStatusMessage('✅ Nouvelles clés créées !');
      } else {
        // Load existing wallets
        const loadedWallets = [
          new ethers.Wallet(key1),
          new ethers.Wallet(key2),
          new ethers.Wallet(key3)
        ];

        setWallets(loadedWallets);
        setDid(savedDid);
        setStatusMessage('✅ Clés chargées !');
      }
    } catch (error) {
      setStatusMessage(`❌ Erreur: ${error.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  // 2. Register DID on server
  const registerDID = async () => {
    if (!wallets || !did) return;

    setIsLoading(true);
    setStatusMessage('Enregistrement du DID...');

    try {
      const publicKeys = wallets.map((wallet, index) => ({
        id: `key${index + 1}`,
        key: wallet.address
      }));

      const response = await fetch(`${BASE_URL}/auth/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          did: did,
          publicKeys: publicKeys,
          quorum: 2
        })
      });

      const result = await response.json();

      if (response.ok) {
        setStatusMessage(`✅ ${result.message}`);
      } else {
        setStatusMessage(`❌ Erreur: ${result.error}`);
      }
    } catch (error) {
      setStatusMessage(`❌ Erreur réseau: ${error.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  // 3. Login (challenge + signature + verification)
  const login = async () => {
    if (!wallets || !did) return;

    setIsLoading(true);
    setStatusMessage('Demande du challenge...');

    try {
      // Step 1: Get challenge
      const challengeResp = await fetch(`${BASE_URL}/auth/challenge/${did}`);

      if (!challengeResp.ok) {
        const errorData = await challengeResp.json();
        throw new Error(errorData.error || 'DID inconnu');
      }

      const challengeData = await challengeResp.json();
      const challenge = challengeData.challenge;

      setStatusMessage('🔐 Signature du challenge...');

      // Step 2: Sign with 2 keys (quorum = 2)
      const signatures = [];
      for (let i = 0; i < 2; i++) {
        const signature = await wallets[i].signMessage(challenge);
        signatures.push({
          keyId: `key${i + 1}`,
          signature: signature
        });
      }

      setStatusMessage('📤 Vérification...');

      // Step 3: Send for verification
      const verifyResp = await fetch(`${BASE_URL}/auth/verify`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          did: did,
          signatures: signatures
        })
      });

      const result = await verifyResp.json();

      if (result.authenticated === true) {
        setStatusMessage(`✅ Authentifié ! ${result.message}`);
      } else {
        setStatusMessage(`❌ Échec: ${result.reason}`);
      }
    } catch (error) {
      setStatusMessage(`❌ Erreur: ${error.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  // Reset all keys
  const resetKeys = async () => {
    localStorage.clear();
    setDid(null);
    setWallets(null);
    await loadOrCreateWallets();
    setStatusMessage('🔄 Clés réinitialisées');
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-8">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <h1 className="text-2xl font-bold text-gray-800">DID Authentication</h1>
          <button
            onClick={() => setShowKeys(!showKeys)}
            className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
          >
            <Info className="w-5 h-5 text-gray-600" />
          </button>
        </div>

        {/* Icon and DID */}
        <div className="flex flex-col items-center mb-8">
          <div className="bg-blue-100 p-6 rounded-full mb-4">
            <Fingerprint className="w-16 h-16 text-blue-600" />
          </div>
          <p className="text-sm text-gray-500 text-center break-all">
            {did || 'Aucun DID'}
          </p>
        </div>

        {/* Status Message */}
        <div className="bg-gray-50 border border-gray-200 rounded-lg p-4 mb-6">
          <p className="text-center text-gray-700">{statusMessage}</p>
        </div>

        {/* Action Buttons */}
        <div className="space-y-3">
          {isLoading ? (
            <div className="flex justify-center py-8">
              <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
            </div>
          ) : (
            <>
              <button
                onClick={registerDID}
                disabled={!wallets}
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 px-4 rounded-lg flex items-center justify-center gap-2 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <Key className="w-5 h-5" />
                1. Enregistrer DID
              </button>

              <button
                onClick={login}
                disabled={!wallets}
                className="w-full bg-green-600 hover:bg-green-700 text-white font-medium py-3 px-4 rounded-lg flex items-center justify-center gap-2 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <LogIn className="w-5 h-5" />
                2. Se connecter
              </button>

              <button
                onClick={() => setShowKeys(!showKeys)}
                disabled={!wallets}
                className="w-full border-2 border-gray-300 hover:border-gray-400 text-gray-700 font-medium py-3 px-4 rounded-lg flex items-center justify-center gap-2 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <Eye className="w-5 h-5" />
                Voir les clés
              </button>

              <button
                onClick={resetKeys}
                className="w-full text-red-600 hover:bg-red-50 font-medium py-3 px-4 rounded-lg flex items-center justify-center gap-2 transition-colors mt-4"
              >
                <RotateCcw className="w-5 h-5" />
                Réinitialiser tout
              </button>
            </>
          )}
        </div>

        {/* Keys Display Modal */}
        {showKeys && wallets && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-xl shadow-2xl max-w-lg w-full p-6">
              <h2 className="text-xl font-bold mb-4">DID & Clés publiques</h2>
              <div className="space-y-3">
                <div className="bg-blue-50 p-3 rounded-lg">
                  <p className="font-semibold text-sm text-gray-700 mb-1">DID:</p>
                  <p className="text-xs text-gray-600 break-all">{did}</p>
                </div>
                {wallets.map((wallet, index) => (
                  <div key={index} className="bg-gray-50 p-3 rounded-lg">
                    <p className="font-semibold text-sm text-gray-700 mb-1">
                      key{index + 1}:
                    </p>
                    <p className="text-xs text-gray-600 break-all font-mono">
                      {wallet.address}
                    </p>
                  </div>
                ))}
              </div>
              <button
                onClick={() => setShowKeys(false)}
                className="w-full mt-4 bg-gray-200 hover:bg-gray-300 text-gray-800 font-medium py-2 px-4 rounded-lg transition-colors"
              >
                Fermer
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DIDAuthApp;
